    <title>role-model runtime</title>
    <link rel="preload" href="/assets/fonts/geist-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin="anonymous" />
    <link rel="preload" href="/assets/fonts/geist-latin-600-normal.woff2" as="font" type="font/woff2" crossorigin="anonymous" />
    <link rel="preload" href="/assets/fonts/geist-mono-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin="anonymous" />
    <link rel="stylesheet" href="/assets/main.css" />
    <script>
      (() => {
        try {
          const key = "role-model-runtime-theme";
          const stored = window.localStorage.getItem(key);
          const theme = stored === "light" || stored === "dark" ? stored : "dark";
          // S178: do NOT write palette tokens inline. index.html used to pin --rm-bg/--rm-fg/
          // --rm-surface/--rm-border/--rm-accent/--rm-secondary to the DARK palette on <html>;
          // inline style beats every stylesheet, so toggling data-theme=light left those tokens
          // dark and produced 1.12:1 text (near-white on #fafafa). The stylesheet already defines
          // both palettes; the shell only needs to select one.
          const root = document.documentElement;
          root.dataset.theme = theme;
          root.classList.toggle("dark", theme === "dark");
          root.classList.toggle("light", theme === "light");
          root.style.colorScheme = theme;
          // S201: the static meta said #0a0a0a (dark) even in light mode. Keep it in step with the
          // theme so the browser chrome does not contradict the page.
          const themeColor = theme === "light" ? "#ffffff" : "#0a0a0a";
          document.querySelector('meta[name="theme-color"]')?.setAttribute("content", themeColor);
        } catch {}
      })();
    </script>
  </head>
  <body>
    <div id="root"></div>
    <script type="module" src="/assets/main.js"></script>
  </body>
</html>
